// E2E for the two features added after the real-analysis work:
//   1. Audit report export (HTML + JSON content generated by the real code)
//   2. Persistence across a page reload
//   3. Reset button clears stored state
//
// Note on downloads: headless Edge cancels all blob: downloads to disk (verified
// with a synthetic blob — the transfer starts then reports "canceled"). So instead
// of reading a file off disk, we intercept the anchor click in-page, read the blob
// back, and assert on the real generated content.
import puppeteer from 'puppeteer-core';

const browser = await puppeteer.launch({
  executablePath: 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',
  headless: true,
  args: ['--disable-gpu', '--no-sandbox'],
});

const page = await browser.newPage();
await page.setViewport({ width: 1600, height: 1000 });
page.on('pageerror', (err) => console.log('[pageerror]', err.message));

const results = {};

page.on('dialog', (dialog) => dialog.accept());

// Capture downloads instead of letting the browser write them to disk
await page.evaluateOnNewDocument(() => {
  // @ts-ignore
  window.__downloads = [];
  const origCreate = document.createElement.bind(document);
  document.createElement = (tag, ...rest) => {
    const el = origCreate(tag, ...rest);
    if (String(tag).toLowerCase() === 'a') {
      const origClick = el.click.bind(el);
      el.click = () => {
        // @ts-ignore
        window.__downloads.push({ filename: el.download, href: el.href });
      };
      void origClick;
    }
    return el;
  };
});

/** Click a button by exact label and return the captured download's text. */
async function exportAndRead(buttonLabel) {
  await page.evaluate((label) => {
    Array.from(document.querySelectorAll('button')).find((b) => b.textContent?.trim() === label)?.click();
  }, buttonLabel);
  await new Promise((r) => setTimeout(r, 600));
  return page.evaluate(async () => {
    const list = window.__downloads;
    const last = list[list.length - 1];
    if (!last) return null;
    const text = await (await fetch(last.href)).text();
    return { filename: last.filename, text };
  });
}

await page.goto('http://localhost:3001/', { waitUntil: 'networkidle2' });
await page.evaluate(() => localStorage.removeItem('trueframe-state'));
await page.reload({ waitUntil: 'networkidle2' });


// Start from a clean slate (persisted state may exist from an earlier run)
await page.evaluate(() => {
  Array.from(document.querySelectorAll('button')).find((b) => b.textContent?.trim() === 'Clear')?.click();
});
await new Promise((r) => setTimeout(r, 300));

// --- Load evidence so a decision can be produced ---
const inputs = await page.$$('input[type="file"]');
await inputs[0].uploadFile('test-fixtures/photo.png');
await page.waitForFunction(
  () =>
    /Sharpness \(var\. of Laplacian\): [1-9]/i.test(document.body.innerText) &&
    /ai inspection (finished|could not check)/i.test(document.body.innerText),
  { timeout: 60000 }
);

await inputs[1].uploadFile('test-fixtures/barcode.png');
await page.waitForFunction(() => document.body.innerText.includes('SN-787-45892-A'), { timeout: 15000 });

await inputs[2].uploadFile('test-fixtures/certificate.pdf');
await page.waitForFunction(() => document.body.innerText.includes('FAA-COC-2024-8891'), { timeout: 20000 });

// A sharp photo is not a damage check. The inspector has to say they looked.
await page.evaluate(() => {
  for (const label of ['No damage', 'Seal intact']) {
    Array.from(document.querySelectorAll('button')).find((b) => b.textContent?.trim() === label)?.click();
  }
});
await new Promise((r) => setTimeout(r, 300));

await page.evaluate(() => {
  Array.from(document.querySelectorAll('button')).find((b) => b.textContent?.trim().startsWith('Run'))?.click();
});
await new Promise((r) => setTimeout(r, 1000));
const decision = (await page.evaluate(() => document.body.innerText)).match(/\b(accept|reject|needs review)\b/i)?.[0];
results.decision = decision || 'none';
// Identity is incomplete until the part serial is actually read. The fixture
// photo is a barcode image, so offline analysis must not pretend it read one.
results.heldForUnreadPart = decision === 'needs review';

// --- Export buttons appear only once a decision exists ---
results.exportButtonsVisible = await page.evaluate(() => {
  const t = document.body.innerText;
  return t.includes('Report') && t.includes('JSON');
});

// --- HTML report ---
const html = await exportAndRead('Report');
results.htmlReportGenerated = Boolean(html);
if (html) {
  results.htmlFilename = /\.html$/.test(html.filename);
  results.htmlHasVerdict = /needs review/i.test(html.text);
  results.htmlSaysPartNotRead = /part itself has not been read/i.test(html.text);
  results.htmlHasSerial = html.text.includes('SN-787-45892-A');
  results.htmlHasCertNo = html.text.includes('FAA-COC-2024-8891');
  results.htmlHasReasoning = html.text.includes('Decision reasoning');
  results.htmlHasEvidenceTable = html.text.includes('<table');
  results.htmlHasOfflineNote = /no external AI service/i.test(html.text);
  results.htmlIsSelfContained = !/<(script|link)\b[^>]*(src|href)=["']http/i.test(html.text);
}

// --- JSON report ---
const json = await exportAndRead('JSON');
results.jsonReportGenerated = Boolean(json);
if (json) {
  const parsed = JSON.parse(json.text);
  results.jsonFilename = /\.json$/.test(json.filename);
  results.jsonDecision = parsed.decision?.decision;
  results.jsonEvidenceCount = parsed.evidence?.length;
  results.jsonPolicyCount = parsed.policies?.length;
  results.jsonHasConflictField = Array.isArray(parsed.decision?.conflicts);
  results.jsonSerial = parsed.evidence?.find((e) => e.metadata?.serialNumber)?.metadata?.serialNumber;
}

// --- Persistence: reload and check the state survived ---
await page.reload({ waitUntil: 'networkidle2' });
await new Promise((r) => setTimeout(r, 1200));
const afterReload = await page.evaluate(() => document.body.innerText);
results.evidenceSurvivesReload = afterReload.includes('SN-787-45892-A') && afterReload.includes('FAA-COC-2024-8891');
results.decisionSurvivesReload = /needs review/i.test(afterReload);

// --- Reset clears it ---
await page.evaluate(() => {
  Array.from(document.querySelectorAll('button')).find((b) => b.textContent?.trim() === 'Clear')?.click();
});
await new Promise((r) => setTimeout(r, 400));
const afterReset = await page.evaluate(() => document.body.innerText);
results.resetClearsEvidence = !afterReset.includes('SN-787-45892-A');
results.resetShowsEmptyState = afterReset.includes('Nothing on the desk yet.');

// And stays cleared after another reload
await page.reload({ waitUntil: 'networkidle2' });
await new Promise((r) => setTimeout(r, 1000));
results.resetPersists = !(await page.evaluate(() => document.body.innerText)).includes('SN-787-45892-A');

console.log('=== REPORT/PERSISTENCE E2E ===');
console.log(JSON.stringify(results, null, 2));

await browser.close();
